using Unity.Burst;
using Unity.Mathematics;

namespace ZE.MechBattle.Projectiles
{
    public static class HighAngleTrajectoryRaycastPointsDefineLogic
    {
        // generated by Deepseek

        /// <summary>
        /// Разбивает параболу на 3 отрезка, гарантированно лежащих ВЫШЕ траектории на величину pad.
        /// </summary>
        [BurstCompile]
        public static HighArcRaycastSegments BuildThreeSegments(
        float3 p0, float3 v0, float g, float tTotal,
        float t1 = 0.25f, float t2 = 0.75f, float pad = 0.05f)
        {
            float3 gVec = new float3(0f, -g, 0f);
            float3 P(float t) => p0 + v0 * t + 0.5f * gVec * t * t;

            float ta = t1 * tTotal;
            float tb = t2 * tTotal;

            // 1. Находим истинную вершину (апекс) параболы
            float tApex = math.clamp(v0.y / g, 0f, tTotal);
            float yApex = P(tApex).y;

            // 2. Получаем точки на самой параболе для привязки по X и Z
            float3 posStart = P(0f);
            float3 posA = P(ta);
            float3 posB = P(tb);
            float3 posEnd = P(tTotal);

            // 3. Формируем 4 вершины для 3-х отрезков
            // Вершина 0: Начало траектории
            float3 v0_pt = posStart;

            // Вершина 1: Конец подъема. X/Z из точки ta, Y поднят до уровня вершины + pad
            float3 v1_pt = new float3(posA.x, yApex + pad, posA.z);

            // Вершина 2: Начало спуска. X/Z из точки tb, Y тот же (гарантирует горизонтальность)
            float3 v2_pt = new float3(posB.x, yApex + pad, posB.z);

            // Вершина 3: Конец траектории (цель)
            float3 v3_pt = posEnd;

            // 4. Собираем итоговые отрезки
            return new
            (
            new TrajectorySegment(v0_pt, v1_pt), // Отрезок 1: Подъем
            new TrajectorySegment(v1_pt, v2_pt), // Отрезок 2: Горизонтальное накрытие сверху
            new TrajectorySegment(v2_pt, v3_pt)  // Отрезок 3: Спуск
            );
        }
    }
}
